313	static int publish_local_status(struct vg_config_mqtt_service *service)
314	{
315	  if (!service->have_active_task)
316	    {
317	      return -ENOENT;
318	    }
319	
320	  memset(&service->status, 0, sizeof(service->status));
321	  if (vg_config_service_query_task(service->config,
322	                                   service->active_task_id,
323	                                   &service->status) != 0)
324	    {
325	      service->have_active_task = false;
326	      return -ENOENT;
327	    }
328	  if (service->have_last_state &&
329	      service->status.state_seq == service->last_state_seq)
330	    {
331	      return -EAGAIN;
332	    }
333	
334	  int ret = publish_state(service, NULL, &service->status);
335	  if (ret == 0 &&
336	      service->status.state != VG_CONFIG_SESSION_OPENED &&
337	      service->status.state != VG_CONFIG_SESSION_VALIDATING &&
338	      service->status.state != VG_CONFIG_SESSION_AWAITING_CONFIRM &&
339	      service->status.state != VG_CONFIG_SESSION_COMMITTING)
340	    {
341	      service->have_active_task = false;
342	    }
343	  return ret;
344	}
