346	int vg_config_mqtt_service_init(
347	  struct vg_config_mqtt_service *service,
348	  struct vg_config_service *config,
349	  const char *device_id,
350	  const struct vg_config_mqtt_service_ports *ports)
351	{
352	  int ret;
353	
354	  if (service == NULL || config == NULL || device_id == NULL ||
355	      strlen(device_id) >= VG_DEVICE_ID_MAX || !ports_valid(ports))
356	    {
357	      return -EINVAL;
358	    }
359	
360	  memset(service, 0, sizeof(*service));
361	  ret = pthread_mutex_init(&service->lock, NULL);
362	  if (ret != 0)
363	    {
364	      return -ret;
365	    }
366	  ret = pthread_cond_init(&service->changed, NULL);
367	  if (ret != 0)
368	    {
369	      pthread_mutex_destroy(&service->lock);
370	      return -ret;
371	    }
372	
373	  service->config = config;
374	  service->ports = *ports;
375	  strcpy(service->device_id, device_id);
376	  service->initialized = true;
377	  return 0;
378	}
