380	int vg_config_mqtt_service_pump(
381	  struct vg_config_mqtt_service *service)
382	{
383	  struct vg_config_mqtt_message *message;
384	  char error[64];
385	  int ret;
386	
387	  if (service == NULL || !service->initialized)
388	    {
389	      return -EINVAL;
390	    }
391	  if (!service->ports.ready(service->ports.ctx))
392	    {
393	      if (service->online)
394	        {
395	          link_lost(service, "network_unavailable");
396	        }
397	      return -ENOTCONN;
398	    }
399	
400	  if (!service->online)
401	    {
402	      ret = vg_config_service_new_link(service->config);
403	      if (ret != 0)
404	        {
405	          set_error(service, "link_identity_failed");
406	          return ret;
407	        }
408	      ret = service->ports.open_connection(service->ports.ctx,
409	                                            service->device_id);
410	      if (ret != 0)
411	        {
412	          set_error(service, ret == -EKEYREJECTED ?
413	                    "tls_verification_failed" :
414	                    ret == -EACCES ? "mqtt_auth_failed" :
415	                    "mqtt_connect_failed");
416	          return ret;
417	        }
418	      service->online = true;
419	      service->pending_ticket = 0;
420	      clear_error(service);
421	    }
422	
423	  ret = service->ports.poll_connection(service->ports.ctx);
424	  if (ret != 0 || !service->ports.online(service->ports.ctx))
425	    {
426	      link_lost(service, "link_lost");
427	      return -ENOTCONN;
428	    }
429	
430	  if (service->pending_ticket != 0)
431	    {
432	      ret = service->ports.acked(service->ports.ctx,
433	                                 service->pending_ticket);
434	      if (ret > 0)
435	        {
436	          service->pending_ticket = 0;
437	        }
438	      else if (service->ports.now_ms(service->ports.ctx) -
439	               service->ticket_since >=
440	               VG_CONFIG_MQTT_ACK_TIMEOUT_MS)
441	        {
442	          link_lost(service, "mqtt_puback_timeout");
443	          return -ETIMEDOUT;
444	        }
445	      else
446	        {
447	          return 0;
448	        }
449	    }
450	
451	  message = service->ports.peek(service->ports.ctx);
452	  if (message != NULL)
453	    {
454	      ret = vg_config_mqtt_request_parse(
455	        message->topic, message->payload, message->length,
456	        service->device_id, true, message->retain, message->qos,
457	        &service->request, message->payload, sizeof(message->payload),
458	        error, sizeof(error));
459	      if (ret == 0)
460	        {
461	          ret = dispatch_request(service, &service->request);
462	          if (ret != 0)
463	            {
464	              set_error(service, "state_publish_failed");
465	            }
466	          service->ports.release(service->ports.ctx);
467	          memset(&service->request, 0, sizeof(service->request));
468	          return ret;
469	        }
470	      service->ports.release(service->ports.ctx);
471	      return 0;
472	    }
473	
474	  ret = publish_local_status(service);
475	  return ret == -ENOENT || ret == -EAGAIN ? 0 : ret;
476	}
