478	static void *service_thread(void *context)
479	{
480	  struct vg_config_mqtt_service *service = context;
481	  uint64_t next_attempt = 0;
482	  unsigned backoff = 0;
483	
484	  for (;;)
485	    {
486	      bool stop;
487	
488	      pthread_mutex_lock(&service->lock);
489	      stop = service->stopping;
490	      pthread_mutex_unlock(&service->lock);
491	      if (stop)
492	        {
493	          break;
494	        }
495	
496	      uint64_t now = service->ports.now_ms(service->ports.ctx);
497	      if (now >= next_attempt)
498	        {
499	          int ret = vg_config_mqtt_service_pump(service);
500	          if (ret == 0)
501	            {
502	              backoff = 0;
503	              next_attempt = now;
504	            }
505	          else if (!service->online)
506	            {
507	              unsigned shift = backoff < 5 ? backoff++ : 5;
508	              next_attempt = now + (1000u << shift);
509	            }
510	        }
511	      service->ports.delay_ms(service->ports.ctx, 100);
512	    }
513	
514	  return NULL;
515	}
516	
517	int vg_config_mqtt_service_start(
518	  struct vg_config_mqtt_service *service)
519	{
520	  pthread_attr_t attr;
521	  int ret;
522	
523	  if (service == NULL || !service->initialized)
524	    {
525	      return -EINVAL;
526	    }
527	
528	  pthread_mutex_lock(&service->lock);
529	  if (service->running)
530	    {
531	      pthread_mutex_unlock(&service->lock);
532	      return -EALREADY;
533	    }
534	  service->stopping = false;
535	  service->running = true;
536	  pthread_mutex_unlock(&service->lock);
537	
538	  ret = pthread_attr_init(&attr);
539	  if (ret == 0)
540	    {
541	      (void)pthread_attr_setstacksize(&attr,
542	                                      VG_CONFIG_MQTT_SERVICE_STACK);
543	      ret = pthread_create(&service->thread, &attr, service_thread,
544	                           service);
545	      pthread_attr_destroy(&attr);
546	    }
547	  if (ret != 0)
548	    {
549	      pthread_mutex_lock(&service->lock);
550	      service->running = false;
551	      pthread_mutex_unlock(&service->lock);
552	      return -ret;
553	    }
554	  return 0;
555	}
556	
557	int vg_config_mqtt_service_stop(
558	  struct vg_config_mqtt_service *service)
559	{
560	  bool running;
561	
562	  if (service == NULL || !service->initialized)
563	    {
564	      return -EINVAL;
565	    }
566	
567	  pthread_mutex_lock(&service->lock);
568	  running = service->running;
569	  service->stopping = true;
570	  pthread_cond_broadcast(&service->changed);
571	  pthread_mutex_unlock(&service->lock);
572	  if (running && pthread_join(service->thread, NULL) != 0)
573	    {
574	      return -EIO;
575	    }
576	  if (service->online)
577	    {
578	      link_lost(service, "service_stopped");
579	    }
580	  pthread_mutex_lock(&service->lock);
581	  service->running = false;
582	  pthread_mutex_unlock(&service->lock);
583	  return 0;
584	}
585	
586	int vg_config_mqtt_service_status(
587	  struct vg_config_mqtt_service *service,
588	  struct vg_config_mqtt_service_status *out)
589	{
590	  if (service == NULL || out == NULL || !service->initialized)
591	    {
592	      return -EINVAL;
593	    }
594	
595	  pthread_mutex_lock(&service->lock);
596	  out->running = service->running;
597	  out->online = service->online;
598	  memcpy(out->error, service->error, sizeof(out->error));
599	  pthread_mutex_unlock(&service->lock);
600	  return 0;
601	}
