1	/****************************************************************************
2	 * app/velaguard/vg_config_confirmation_worker.c
3	 ****************************************************************************/
4	
5	#include <errno.h>
6	#include <string.h>
7	
8	#include "vg_config_confirmation_worker.h"
9	
10	#define VG_CONFIG_CONFIRMATION_WORKER_STACK 16384
11	
12	static int worker_load_pending(
13	  void *ctx,
14	  struct vg_config_pending_preview *out)
15	{
16	  struct vg_config_confirmation_worker *worker = ctx;
17	
18	  if (worker == NULL || !worker->initialized || worker->service == NULL)
19	    {
20	      return -ENOENT;
21	    }
22	
23	  return vg_config_service_pending_preview(worker->service, out);
24	}
25	
26	static int worker_submit(
27	  void *ctx,
28	  const struct vg_config_confirmation_action *action)
29	{
30	  struct vg_config_confirmation_worker *worker = ctx;
31	  int ret = 0;
32	
33	  if (worker == NULL || action == NULL || !worker->initialized)
34	    {
35	      return -EINVAL;
36	    }
37	
38	  pthread_mutex_lock(&worker->lock);
39	  if (worker->stopping || !worker->started)
40	    {
41	      ret = -EPIPE;
42	    }
43	  else if (worker->queued)
44	    {
45	      ret = -EBUSY;
46	    }
47	  else
48	    {
49	      worker->action = *action;
50	      worker->queued = true;
51	      pthread_cond_signal(&worker->changed);
52	    }
53	
54	  pthread_mutex_unlock(&worker->lock);
55	  return ret;
56	}
57	
58	static void *worker_main(void *ctx)
59	{
60	  struct vg_config_confirmation_worker *worker = ctx;
61	
62	  for (;;)
63	    {
64	      struct vg_config_confirmation_action action;
65	      struct vg_config_task_status status;
66	      bool alarm_active;
67	      bool stop;
68	
69	      pthread_mutex_lock(&worker->lock);
70	      while (!worker->queued && !worker->stopping)
71	        {
72	          pthread_cond_wait(&worker->changed, &worker->lock);
73	        }
74	
75	      stop = worker->stopping && !worker->queued;
76	      if (stop)
77	        {
78	          pthread_mutex_unlock(&worker->lock);
79	          break;
80	        }
81	
82	      action = worker->action;
83	      memset(&worker->action, 0, sizeof(worker->action));
84	      worker->queued = false;
85	      pthread_cond_broadcast(&worker->changed);
86	      pthread_mutex_unlock(&worker->lock);
87	
88	      alarm_active = worker->alarm_active != NULL &&
89	                     worker->alarm_active(worker->alarm_ctx);
90	      if (alarm_active)
91	        {
92	          (void)vg_config_confirmation_sync(worker->confirmation, true);
93	          continue;
94	        }
95	
96	      if (!vg_config_confirmation_claim(worker->confirmation, &action))
97	        {
98	          continue;
99	        }
100	
101	      memset(&status, 0, sizeof(status));
102	      if (action.kind == VG_CONFIG_CONFIRMATION_CONFIRM)
103	        {
104	          (void)vg_config_service_confirm(worker->service,
105	                                          &action.request.confirm,
106	                                          &status);
107	        }
108	      else
109	        {
110	          (void)vg_config_service_cancel_local(worker->service,
111	                                               &action.request.cancel,
112	                                               &status);
113	        }
114	
115	      memset(&action, 0, sizeof(action));
116	      memset(&status, 0, sizeof(status));
117	    }
118	
119	  return NULL;
120	}
121	
122	int vg_config_confirmation_worker_init(
123	  struct vg_config_confirmation_worker *worker,
124	  struct vg_config_confirmation *confirmation,
125	  struct vg_config_service *service,
126	  bool (*alarm_active)(void *ctx),
127	  void *alarm_ctx)
128	{
129	  int ret;
130	
131	  if (worker == NULL || confirmation == NULL || service == NULL)
132	    {
133	      return -EINVAL;
134	    }
135	
136	  memset(worker, 0, sizeof(*worker));
137	  ret = pthread_mutex_init(&worker->lock, NULL);
138	  if (ret != 0)
139	    {
140	      return -ret;
141	    }
142	
143	  ret = pthread_cond_init(&worker->changed, NULL);
144	  if (ret != 0)
145	    {
146	      pthread_mutex_destroy(&worker->lock);
147	      memset(worker, 0, sizeof(*worker));
148	      return -ret;
149	    }
150	
151	  worker->confirmation = confirmation;
152	  worker->service = service;
153	  worker->alarm_active = alarm_active;
154	  worker->alarm_ctx = alarm_ctx;
155	  worker->initialized = true;
156	  return 0;
157	}
158	
159	int vg_config_confirmation_worker_ports(
160	  struct vg_config_confirmation_worker *worker,
161	  struct vg_config_confirmation_ports *ports)
162	{
163	  if (worker == NULL || ports == NULL || !worker->initialized)
164	    {
165	      return -EINVAL;
166	    }
167	
168	  memset(ports, 0, sizeof(*ports));
169	  ports->load_pending = worker_load_pending;
170	  ports->submit = worker_submit;
171	  ports->ctx = worker;
172	  return 0;
173	}
174	
175	int vg_config_confirmation_worker_start(
176	  struct vg_config_confirmation_worker *worker)
177	{
178	  pthread_attr_t attr;
179	  int ret;
180	
181	  if (worker == NULL || !worker->initialized)
182	    {
183	      return -EINVAL;
184	    }
185	
186	  pthread_mutex_lock(&worker->lock);
187	  if (worker->started)
188	    {
189	      pthread_mutex_unlock(&worker->lock);
190	      return -EALREADY;
191	    }
192	  worker->stopping = false;
193	  worker->started = true;
194	  pthread_mutex_unlock(&worker->lock);
195	
196	  ret = pthread_attr_init(&attr);
197	  if (ret == 0)
198	    {
199	      (void)pthread_attr_setstacksize(
200	        &attr, VG_CONFIG_CONFIRMATION_WORKER_STACK);
201	      ret = pthread_create(&worker->thread, &attr, worker_main, worker);
202	      pthread_attr_destroy(&attr);
203	    }
204	
205	  if (ret != 0)
206	    {
207	      pthread_mutex_lock(&worker->lock);
208	      worker->started = false;
209	      pthread_mutex_unlock(&worker->lock);
210	      return -ret;
211	    }
212	
213	  return 0;
214	}
215	
216	int vg_config_confirmation_worker_stop(
217	  struct vg_config_confirmation_worker *worker)
218	{
219	  bool started;
220	
221	  if (worker == NULL || !worker->initialized)
222	    {
223	      return -EINVAL;
224	    }
225	
226	  pthread_mutex_lock(&worker->lock);
227	  started = worker->started;
228	  worker->stopping = true;
229	  pthread_cond_broadcast(&worker->changed);
230	  pthread_mutex_unlock(&worker->lock);
231	
232	  if (started && pthread_join(worker->thread, NULL) != 0)
233	    {
234	      return -EIO;
235	    }
236	
237	  pthread_mutex_lock(&worker->lock);
238	  worker->started = false;
239	  pthread_mutex_unlock(&worker->lock);
240	  return 0;
241	}
