16	enum vg_config_confirmation_action_kind_e
17	{
18	  VG_CONFIG_CONFIRMATION_CONFIRM = 0,
19	  VG_CONFIG_CONFIRMATION_CANCEL
20	};
21	
22	struct vg_config_confirmation_action
23	{
24	  enum vg_config_confirmation_action_kind_e kind;
