72	  struct vg_config_confirmation *confirmation);
73	int vg_config_confirmation_snapshot(
74	  struct vg_config_confirmation *confirmation,
75	  struct vg_config_pending_preview *out);
76	const struct vg_config_pending_preview *vg_config_confirmation_peek(
77	  struct vg_config_confirmation *confirmation);
78	
79	int vg_config_confirmation_submit(
80	  struct vg_config_confirmation *confirmation,
81	  enum vg_config_confirmation_action_kind_e kind,
82	  bool alarm_active);
83	
84	/* The worker calls this immediately before touching the configuration service.
85	 * A matching action can be claimed once; alarm, expiry, a new candidate or a
86	 * replacement action invalidates every older action. */
87	bool vg_config_confirmation_claim(
88	  struct vg_config_confirmation *confirmation,
89	  const struct vg_config_confirmation_action *action);
