70	static int random_bytes(void *ctx, uint8_t *out, size_t length)
71	{
72	  size_t used = 0;
73	  int fd;
74	
75	  (void)ctx;
76	  if (out == NULL)
77	    {
78	      return -EINVAL;
79	    }
80	#ifdef __NuttX__
81	  fd = open("/dev/urandom", O_RDONLY);
82	  if (fd < 0)
83	    {
84	      return -errno;
85	    }
86	  while (used < length)
87	    {
88	      ssize_t got = read(fd, out + used, length - used);
89	      if (got < 0 && errno == EINTR)
90	        {
91	          continue;
92	        }
93	      if (got <= 0)
94	        {
95	          close(fd);
96	          memset(out, 0, length);
97	          return -EIO;
98	        }
99	      used += (size_t)got;
100	    }
101	  if (close(fd) != 0)
102	    {
103	      memset(out, 0, length);
104	      return -errno;
105	    }
106	  return 0;
107	#else
108	  while (used < length)
109	    {
110	      out[used++] = (uint8_t)(0xa5u ^ used);
111	    }
112	  return 0;
113	#endif
114	}
