244	{
245	  struct vg_config_service_ports config_ports;
246	  struct vg_config_mqtt_service_ports wire_ports;
247	  int ret;
248	
249	  if (g_runtime_ptr != NULL && g_runtime.started)
250	    {
251	      return 0;
252	    }
