255	    {
256	      return -EAGAIN;
257	    }
258	  if (vg_ota_trust_ca() == NULL || vg_ota_trust_ca()[0] == '\0')
259	    {
260	      return -ENOKEY;
261	    }
262	  g_runtime_ptr = malloc(sizeof(*g_runtime_ptr));
263	  if (g_runtime_ptr == NULL)
264	    {
265	      return -ENOMEM;
266	    }
267	  *g_runtime_ptr = g_runtime_initializer;
268	#ifdef __NuttX__
269	  if (mallinfo().fordblks < VG_CONFIG_MQTT_RUNTIME_HEAP_RESERVE)
270	    {
271	      ret = -ENOMEM;
272	      goto failed_runtime;
273	    }
274	#endif
275	  ret = vg_config_mqtt_credentials_load(&g_runtime.credentials);
276	  if (ret != 0)
277	    {
278	      return ret;
279	    }
280	
281	  ret = vg_config_file_source_init(
282	    &g_runtime.table_source, CONFIG_VG_DISCOVER_POINTS_PATH,
283	    CONFIG_VG_STORE_ROOT);
284	  if (ret != 0)
285	    {
286	      goto failed_credentials;
287	    }
