289	  memset(&config_ports, 0, sizeof(config_ports));
290	  config_ports.load_table = load_table;
291	  config_ports.random_bytes = random_bytes;
292	  config_ports.now_ms = monotonic_ms;
293	  config_ports.ctx = &g_runtime.table_source;
294	  config_ports.commit_table = commit_table;
295	  config_ports.notify_table = notify_table;
296	  ret = vg_config_service_init(&g_runtime.config, &config_ports);
297	  if (ret != 0)
298	    {
299	      goto failed_credentials;
300	    }
301	
302	  memset(&wire_ports, 0, sizeof(wire_ports));
303	  wire_ports.open_connection = wire_open;
304	  wire_ports.poll_connection = wire_poll;
305	  wire_ports.online = wire_online;
306	  wire_ports.close_connection = wire_close;
307	  wire_ports.peek = wire_peek;
308	  wire_ports.release = wire_release;
309	  wire_ports.publish = wire_publish;
310	  wire_ports.acked = wire_acked;
311	  wire_ports.ready = wire_ready;
312	  wire_ports.now_ms = wire_now;
313	  wire_ports.delay_ms = wire_delay;
314	  wire_ports.ctx = &g_runtime;
315	  ret = vg_config_mqtt_service_init(
316	    &g_runtime.service, &g_runtime.config, vg_device_id(), &wire_ports);
317	  if (ret != 0)
318	    {
319	      goto failed_credentials;
320	    }
321	  ret = vg_config_mqtt_service_start(&g_runtime.service);
322	  if (ret != 0)
323	    {
324	      goto failed_credentials;
325	    }
326	
327	  g_runtime.started = true;
328	  return 0;
329	
330	failed_credentials:
331	  memset(&g_runtime.credentials, 0, sizeof(g_runtime.credentials));
332	failed_runtime:
333	  memset(g_runtime_ptr, 0, sizeof(*g_runtime_ptr));
334	  free(g_runtime_ptr);
335	  g_runtime_ptr = NULL;
336	  return ret;
