349	int vg_config_mqtt_runtime_status(
350	  struct vg_config_mqtt_runtime_status *out)
351	{
352	  struct vg_config_mqtt_service_status status;
353	  int ret = 0;
354	
355	  if (out == NULL)
356	    {
357	      return -EINVAL;
358	    }
359	  memset(out, 0, sizeof(*out));
360	  pthread_mutex_lock(&g_start_lock);
361	  out->initialized = g_runtime_ptr != NULL && g_runtime.started;
362	  if (!out->initialized)
363	    {
364	#ifdef __NuttX__
365	      struct stat st;
366	#endif
367	      snprintf(out->error, sizeof(out->error), "%s",
368	               vg_ota_trust_ca() == NULL || vg_ota_trust_ca()[0] == '\0' ?
369	               "trust_unconfigured" :
370	#ifdef __NuttX__
371	               stat(VG_CONFIG_MQTT_CREDENTIALS_FILE, &st) == 0 ?
372	               "restart_required" :
373	#endif
374	               "credentials_unconfigured");
375	      goto done;
376	    }
377	  if (vg_config_mqtt_service_status(&g_runtime.service, &status) != 0)
378	    {
379	      ret = -EIO;
380	      goto done;
381	    }
382	  out->running = status.running;
383	  out->online = status.online;
384	  memcpy(out->error, status.error, sizeof(out->error));
385	
386	done:
387	  pthread_mutex_unlock(&g_start_lock);
388	  return ret;
389	}
