419	int vg_config_mqtt_runtime_bind_confirmation(
420	  struct vg_config_confirmation *confirmation,
421	  bool (*alarm_active)(void *ctx),
422	  void *alarm_ctx)
423	{
424	  struct vg_config_confirmation_ports ports;
425	  int ret;
426	
427	  if (confirmation == NULL)
428	    {
429	      return -EINVAL;
430	    }
431	  pthread_mutex_lock(&g_start_lock);
432	  if (g_runtime_ptr == NULL || !g_runtime.started)
433	    {
434	      pthread_mutex_unlock(&g_start_lock);
435	      return -EAGAIN;
436	    }
437	  if (g_runtime.worker_initialized)
438	    {
439	      pthread_mutex_unlock(&g_start_lock);
440	      return -EALREADY;
441	    }
442	
443	  ret = vg_config_confirmation_worker_init(
444	    &g_runtime.worker, confirmation, &g_runtime.config,
445	    alarm_active, alarm_ctx);
446	  if (ret != 0)
447	    {
448	      pthread_mutex_unlock(&g_start_lock);
449	      return ret;
450	    }
451	  ret = vg_config_confirmation_worker_ports(&g_runtime.worker, &ports);
452	  if (ret == 0)
453	    {
454	      ret = vg_config_confirmation_bind(confirmation, &ports);
455	    }
456	  if (ret == 0)
457	    {
458	      ret = vg_config_confirmation_worker_start(&g_runtime.worker);
459	    }
460	  if (ret != 0)
461	    {
462	      pthread_mutex_unlock(&g_start_lock);
463	      return ret;
464	    }
465	
466	  g_runtime.worker_initialized = true;
467	  pthread_mutex_unlock(&g_start_lock);
468	  return 0;
469	}
