static void on_key(lv_event_t * e)
{
    uint32_t key;
    if(lv_event_get_code(e) != LV_EVENT_KEY) return;
    key = lv_event_get_key(e);

    if(key == LV_KEY_ESC) {
        vg_nav_back();
        return;
    }
    if(key >= '1' && key <= '6') {
        vg_model_set_scenario((vg_scenario_t)(key - '0'));
    }
}

