    if(g == NULL) {
        g = lv_group_create();
        lv_group_set_default(g);
    }
    lv_group_add_obj(g, lv_screen_active());
    lv_obj_add_event_cb(lv_screen_active(), on_key, LV_EVENT_KEY, NULL);

