15	struct confirmation_identity
16	{
17	  char task_id[VG_CONFIG_ID_MAX];
18	  char session_id[VG_CONFIG_HEX32_LEN];
19	  uint32_t revision;
20	  bool has_base_hash;
21	  char base_hash[VG_CONFIG_HASH_LEN];
22	  char payload_hash[VG_CONFIG_HASH_LEN];
23	  char candidate_hash[VG_CONFIG_HASH_LEN];
24	  char confirmation_id[VG_CONFIG_HEX32_LEN];
25	};
26	
27	static void capture_identity(const struct vg_config_pending_preview *pending,
28	                             struct confirmation_identity *identity)
29	{
30	  memset(identity, 0, sizeof(*identity));
31	  memcpy(identity->task_id, pending->task_id, sizeof(identity->task_id));
32	  memcpy(identity->session_id, pending->session_id,
33	         sizeof(identity->session_id));
34	  identity->revision = pending->revision;
35	  identity->has_base_hash = pending->has_base_hash;
36	  memcpy(identity->base_hash, pending->base_hash,
37	         sizeof(identity->base_hash));
38	  memcpy(identity->payload_hash, pending->payload_hash,
39	         sizeof(identity->payload_hash));
40	  memcpy(identity->candidate_hash, pending->candidate_hash,
41	         sizeof(identity->candidate_hash));
42	  memcpy(identity->confirmation_id, pending->confirmation_id,
43	         sizeof(identity->confirmation_id));
44	}
45	
46	static bool same_identity(const struct confirmation_identity *a,
47	                          const struct confirmation_identity *b)
48	{
49	  return strcmp(a->task_id, b->task_id) == 0 &&
50	         strcmp(a->session_id, b->session_id) == 0 &&
51	         a->revision == b->revision &&
52	         same_hash(a->has_base_hash, a->base_hash,
53	                   b->has_base_hash, b->base_hash) &&
54	         strcmp(a->payload_hash, b->payload_hash) == 0 &&
55	         strcmp(a->candidate_hash, b->candidate_hash) == 0 &&
56	         strcmp(a->confirmation_id, b->confirmation_id) == 0;
57	}
58	
59	static void invalidate_locked(struct vg_config_confirmation *confirmation)
60	{
61	  memset(&confirmation->pending, 0, sizeof(confirmation->pending));
62	  confirmation->have_pending = false;
63	  confirmation->visible = false;
64	  confirmation->suppressed = false;
65	  confirmation->action_in_flight = false;
66	  confirmation->action_claimed = false;
67	  confirmation->generation++;
68	  if (confirmation->generation == 0)
69	    {
70	      confirmation->generation = 1;
71	    }
72	}
73	
74	static void apply_loaded_locked(
75	  struct vg_config_confirmation *confirmation,
76	  bool changed,
77	  bool alarm_active)
78	{
79	  bool alarm_changed = confirmation->alarm_blocked != alarm_active;
80	
81	  if (alarm_changed)
82	    {
83	      confirmation->generation++;
84	      if (confirmation->generation == 0)
85	        {
86	          confirmation->generation = 1;
87	        }
88	      if (alarm_active)
89	        {
90	          confirmation->suppressed = false;
91	          confirmation->action_in_flight = false;
92	          confirmation->action_claimed = false;
93	        }
94	    }
95	  confirmation->alarm_blocked = alarm_active;
96	
97	  if (changed)
98	    {
99	      confirmation->have_pending = confirmation->pending.valid;
100	      confirmation->suppressed = false;
101	      confirmation->action_in_flight = false;
102	      confirmation->action_claimed = false;
103	      confirmation->generation++;
104	      if (confirmation->generation == 0)
105	        {
106	          confirmation->generation = 1;
107	        }
108	    }
109	
110	  confirmation->visible =
111	    confirmation->have_pending && !confirmation->alarm_blocked &&
112	    !confirmation->suppressed && !confirmation->action_in_flight;
113	}
