115	int vg_config_confirmation_init(
116	  struct vg_config_confirmation *confirmation,
117	  const struct vg_config_confirmation_ports *ports)
118	{
119	  int ret;
120	
121	  if (confirmation == NULL)
122	    {
123	      return -EINVAL;
124	    }
125	
126	  memset(confirmation, 0, sizeof(*confirmation));
127	  ret = pthread_mutex_init(&confirmation->lock, NULL);
128	  if (ret != 0)
129	    {
130	      memset(confirmation, 0, sizeof(*confirmation));
131	      return -ret;
132	    }
133	
134	  confirmation->initialized = true;
135	  confirmation->generation = 1;
136	  if (ports != NULL)
137	    {
138	      confirmation->ports = *ports;
139	    }
140	
141	  return 0;
142	}
