144	int vg_config_confirmation_bind(
145	  struct vg_config_confirmation *confirmation,
146	  const struct vg_config_confirmation_ports *ports)
147	{
148	  if (confirmation == NULL || !confirmation->initialized ||
149	      ports == NULL || ports->load_pending == NULL ||
150	      ports->submit == NULL)
151	    {
152	      return -EINVAL;
153	    }
154	
155	  pthread_mutex_lock(&confirmation->lock);
156	  confirmation->ports = *ports;
157	  invalidate_locked(confirmation);
158	  pthread_mutex_unlock(&confirmation->lock);
159	  return 0;
160	}
