162	void vg_config_confirmation_deinit(
163	  struct vg_config_confirmation *confirmation)
164	{
165	  if (confirmation == NULL || !confirmation->initialized)
166	    {
167	      return;
168	    }
169	
170	  pthread_mutex_destroy(&confirmation->lock);
171	  memset(confirmation, 0, sizeof(*confirmation));
172	}
173	
174	int vg_config_confirmation_sync(struct vg_config_confirmation *confirmation,
175	                                bool alarm_active)
176	{
177	  struct confirmation_identity old_identity;
178	  struct confirmation_identity new_identity;
179	  struct vg_config_confirmation_ports ports;
180	  bool changed;
181	  bool have_loaded = false;
182	  bool had_pending;
183	  int ret;
184	
185	  if (confirmation == NULL || !confirmation->initialized)
186	    {
187	      return -EINVAL;
188	    }
189	
190	  pthread_mutex_lock(&confirmation->lock);
191	  had_pending = confirmation->have_pending;
192	  if (had_pending)
193	    {
194	      capture_identity(&confirmation->pending, &old_identity);
195	    }
196	
197	  ports = confirmation->ports;
198	  memset(&confirmation->pending, 0, sizeof(confirmation->pending));
199	  ret = ports.load_pending != NULL ?
200	        ports.load_pending(ports.ctx, &confirmation->pending) : -ENOSYS;
201	  if (ret == 0 && confirmation->pending.valid)
202	    {
203	      have_loaded = true;
204	    }
205	
206	  if (!have_loaded)
207	    {
208	      if (had_pending || confirmation->visible ||
209	          confirmation->suppressed || confirmation->action_in_flight)
210	        {
211	          invalidate_locked(confirmation);
212	        }
213	      confirmation->alarm_blocked = alarm_active;
214	      pthread_mutex_unlock(&confirmation->lock);
215	      return ret == -ENOENT || ret == -ENOSYS || ret == -ESTALE ? 0 : ret;
216	    }
217	
218	  capture_identity(&confirmation->pending, &new_identity);
219	  changed = !had_pending || !same_identity(&old_identity, &new_identity);
220	  apply_loaded_locked(confirmation, changed, alarm_active);
221	  pthread_mutex_unlock(&confirmation->lock);
222	  return 0;
223	}
