225	bool vg_config_confirmation_is_visible(
226	  struct vg_config_confirmation *confirmation)
227	{
228	  bool visible;
229	
230	  if (confirmation == NULL || !confirmation->initialized)
231	    {
232	      return false;
233	    }
234	
235	  pthread_mutex_lock(&confirmation->lock);
236	  visible = confirmation->visible;
237	  pthread_mutex_unlock(&confirmation->lock);
238	  return visible;
239	}
