157	static void expire_if_due(struct vg_config_service *service, bool *release)
158	{
159	  uint64_t now;
160	
161	  *release = false;
162	  if (!service->session_active)
163	    {
164	      return;
165	    }
166	  if (service->session.state == VG_CONFIG_SESSION_COMMITTING)
167	    {
168	      return;
169	    }
170	
171	  now = service->ports.now_ms(service->ports.ctx);
172	  if (now < service->lease_deadline_ms)
173	    {
174	      return;
175	    }
176	
177	  service->session.state = VG_CONFIG_SESSION_EXPIRED;
178	  service->session.lease_remaining_ms = 0;
179	  service->session.state_seq++;
180	  set_error(&service->session, "lease_expired", false);
181	  service->session_active = false;
182	  service->has_put_request = false;
183	  memset(service->put_req_id, 0, sizeof(service->put_req_id));
184	  memset(service->put_request_hash, 0, sizeof(service->put_request_hash));
185	  memset(&service->pending, 0, sizeof(service->pending));
186	  *release = service->remote_gate_token != 0;
187	}
