190	                        const struct vg_config_task_status *source,
191	                        struct vg_config_task_status *out)
192	{
193	  uint64_t now = service->ports.now_ms(service->ports.ctx);
194	
195	  *out = *source;
196	  if (service->session_active &&
197	      strcmp(out->task_id, service->session.task_id) == 0)
198	    {
199	      out->lease_remaining_ms =
200	        now < service->lease_deadline_ms ?
201	        service->lease_deadline_ms - now : 0;
202	    }
203	  else
204	    {
205	      out->lease_remaining_ms = 0;
206	    }
207	}
