724	static bool text_without_controls(const char *value, size_t maximum,
725	                                  bool allow_lf)
726	{
727	  const uint8_t *cursor;
728	  const uint8_t *end;
729	  size_t length;
730	
731	  if (value == NULL)
732	    {
733	      return false;
734	    }
735	
736	  length = strlen(value);
737	  if (length < 1 || length > maximum)
738	    {
739	      return false;
740	    }
741	
742	  cursor = (const uint8_t *)value;
743	  end = cursor + length;
744	  while (cursor < end)
745	    {
746	      uint32_t codepoint;
747	      size_t used;
748	
749	      if (utf8_codepoint(cursor, (size_t)(end - cursor),
750	                         &codepoint, &used) != 0)
751	        {
752	          return false;
753	        }
754	      if ((codepoint < 0x20 && (!allow_lf || codepoint != '\n')) ||
755	          (codepoint >= 0x7f && codepoint <= 0x9f))
756	        {
757	          return false;
758	        }
759	      cursor += used;
760	    }
761	
762	  return true;
763	}
